// Firebase Integration Test Utility
import { initializeFirebaseServices, getAuthService, getFirestoreService, getStorageService } from '../services/firebase';

export class FirebaseTestSuite {
  constructor() {
    this.results = {
      initialization: { status: 'pending', message: '', timestamp: null },
      auth: { status: 'pending', message: '', timestamp: null },
      firestore: { status: 'pending', message: '', timestamp: null },
      storage: { status: 'pending', message: '', timestamp: null }
    };
  }

  async runAllTests() {
    console.log('🧪 Starting Firebase Integration Tests...');

    try {
      console.log('📋 Test 1/3: Initialization...');
      await this.testInitialization();

      console.log('📋 Test 2/3: Firestore...');
      await this.testFirestore();

      console.log('📋 Test 3/3: Storage...');
      await this.testStorage();

      console.log('✅ All tests completed!');
    } catch (error) {
      console.error('❌ Test suite error:', error);
      throw error;
    }

    return this.results;
  }

  async testInitialization() {
    try {
      initializeFirebaseServices();
      this.results.initialization = {
        status: 'success',
        message: 'Firebase services initialized successfully',
        timestamp: new Date().toISOString()
      };
      console.log('✅ Firebase Initialization: PASSED');
    } catch (error) {
      this.results.initialization = {
        status: 'error',
        message: `Initialization failed: ${error.message}`,
        timestamp: new Date().toISOString()
      };
      console.error('❌ Firebase Initialization: FAILED', error);
    }
  }

  async testFirestore() {
    try {
      const firestoreService = getFirestoreService();

      // Test creating a test document
      const testData = {
        test: true,
        message: 'Firebase integration test',
        timestamp: Date.now()
      };

      const result = await firestoreService.addItem({
        ...testData,
        title: 'Test Item - Firebase Integration',
        price: 1,
        seller_id: 'test-user',
        category: 'Test',
        description: 'This is a test item to verify Firestore integration'
      });

      if (result.success) {
        // Test reading the document back
        const items = await firestoreService.getItems([], 5);

        if (items.success && items.data.length > 0) {
          this.results.firestore = {
            status: 'success',
            message: `Firestore working! Created item ${result.data}, found ${items.data.length} items`,
            timestamp: new Date().toISOString(),
            data: { itemId: result.data, itemCount: items.data.length }
          };
          console.log('✅ Firestore: PASSED');
        } else {
          throw new Error('Failed to read back created item');
        }
      } else {
        throw new Error(result.error || 'Failed to create test item');
      }
    } catch (error) {
      this.results.firestore = {
        status: 'error',
        message: `Firestore test failed: ${error.message}`,
        timestamp: new Date().toISOString()
      };
      console.error('❌ Firestore: FAILED', error);
    }
  }

  async testStorage() {
    try {
      const storageService = getStorageService();

      // Create a small test file (1x1 pixel PNG)
      const testImageBlob = await this.createTestImage();

      // Test upload
      const uploadResult = await storageService.uploadImage(testImageBlob, `test-images/integration-test-${Date.now()}.png`);

      if (uploadResult.success) {
        this.results.storage = {
          status: 'success',
          message: `Storage working! Uploaded test image: ${uploadResult.url}`,
          timestamp: new Date().toISOString(),
          data: { imageUrl: uploadResult.url }
        };
        console.log('✅ Firebase Storage: PASSED');
      } else {
        throw new Error(uploadResult.error || 'Failed to upload test image');
      }
    } catch (error) {
      this.results.storage = {
        status: 'error', 
        message: `Storage test failed: ${error.message}`,
        timestamp: new Date().toISOString()
      };
      console.error('❌ Firebase Storage: FAILED', error);
    }
  }

  createTestImage() {
    // Create a minimal 1x1 pixel PNG as a Blob for testing
    const canvas = document.createElement('canvas');
    canvas.width = 1;
    canvas.height = 1;
    const ctx = canvas.getContext('2d');
    ctx.fillStyle = '#667eea'; // SwipeCity brand color
    ctx.fillRect(0, 0, 1, 1);

    return new Promise((resolve) => {
      canvas.toBlob((blob) => {
        resolve(blob);
      }, 'image/png');
    });
  }

  generateReport() {
    const report = {
      timestamp: new Date().toISOString(),
      summary: {
        total: Object.keys(this.results).length,
        passed: Object.values(this.results).filter(r => r.status === 'success').length,
        failed: Object.values(this.results).filter(r => r.status === 'error').length,
        pending: Object.values(this.results).filter(r => r.status === 'pending').length
      },
      details: this.results
    };

    console.log('📊 Firebase Test Report:', report);
    return report;
  }
}

// Export a convenience function to run tests
export const runFirebaseTests = async () => {
  const testSuite = new FirebaseTestSuite();
  await testSuite.runAllTests();
  return testSuite.generateReport();
};
